473	    fn render_step_templates(
474	        &self,
475	        frame: &mut Frame,
476	        area: Rect,
477	        hits: &mut HitMap,
478	        mode: DegradeMode,
479	    ) {
480	        // Create card — DegradeMode flows through from allocator
481	        let card = SectionCard::new()
482	            .title("Add templates?")
483	            .degrade_mode(mode);
484	        let inner = card.render(frame, area);
485	
486	        if inner.height == 0 || self.step_templates.is_empty() {
487	            return;
488	        }
489	
490	        // Only show helper text in Full mode — Compact/Minimal need all space for the list
491	        let mut y = inner.y;
492	        let mut lines_used = 0u16;
493	
494	        if mode == DegradeMode::Full {
495	            let helper_text = "Bivvy has templates available for commonly used package managers \
496	                               and tools found in your project to help you get started quickly. \
497	                               Select any you'd like to include. Leave out the ones you don't.";
498	
499	            let helper_style = Style::default().fg(Palette::TEXT_DIM);
500	            let max_width = inner.width as usize;
501	            let words: Vec<&str> = helper_text.split_whitespace().collect();
502	            let mut current_line = String::new();
503	
504	            for word in words {
505	                let test_line = if current_line.is_empty() {
506	                    word.to_string()
507	                } else {
508	                    format!("{} {}", current_line, word)
509	                };
510	
511	                if test_line.len() <= max_width {
512	                    current_line = test_line;
513	                } else {
514	                    if y < inner.y + inner.height {
515	                        frame
516	                            .buffer_mut()
517	                            .set_string(inner.x, y, &current_line, helper_style);
518	                        y += 1;
519	                        lines_used += 1;
520	                    }
521	                    current_line = word.to_string();
522	                }
523	            }
524	            if !current_line.is_empty() && y < inner.y + inner.height {
525	                frame
526	                    .buffer_mut()
527	                    .set_string(inner.x, y, &current_line, helper_style);
528	                y += 1;
529	                lines_used += 1;
530	            }
531	
532	            // Spacing after helper text
533	            y += 1;
534	        }
535	
536	        // Calculate remaining area for card list
537	        let spacing_offset = if mode == DegradeMode::Full {
538	            lines_used + 2
539	        } else {
540	            0
541	        };
542	        let list_area = Rect {
543	            x: inner.x,
544	            y,
545	            width: inner.width,
546	            height: inner.height.saturating_sub(spacing_offset),
547	        };
548	
549	        if list_area.height == 0 {
550	            return;
551	        }
552	
553	        // Build card list items (multi-select behavior is in toggle_selection)
554	        let items: Vec<CardListItem> = self
555	            .step_templates
556	            .iter()
557	            .enumerate()
558	            .map(|(i, t)| {
559	                CardListItem::new(&t.name, &t.reason, t.selected, i == self.selected_index)
560	            })
561	            .collect();
562	
563	        let card_list = CardList::new(items)
564	            .spacing(CardListSpacing::Compact)
565	            .scroll_offset(self.scroll_offset);
566	
567	        // Update visible_count for scrolling calculations
568	        let visible = card_list.items_that_fit(list_area.height);
569	        self.visible_count.set(visible);
570	
571	        card_list.render(frame, list_area);
572	
573	        // Register hit regions for each visible step template item.
574	        // CardList default card_height is 4; compact spacing has gap 0.
575	        let card_height = 4u16;
576	        let gap = CardListSpacing::Compact.gap();
577	        let start = self.scroll_offset;
578	        let end = (start + visible).min(self.step_templates.len());
579	        let mut item_y = list_area.y;
580	        for i in start..end {
581	            let item_rect = Rect::new(list_area.x, item_y, list_area.width, card_height);
582	            hits.register(HitRegion {
583	                area: item_rect,
584	                action: Action::Toggle,
585	                index: Some(i),
586	                click: ClickBehavior::FocusThenFire,
587	            });
588	            item_y += card_height + gap;
589	        }
590	    }
