1	//! Event-driven presenter for display-only operations.
2	//!
3	//! Implements [`EventConsumer`] to handle non-interactive UI output in
4	//! response to events. Interactive prompts remain in the orchestrator —
5	//! this presenter handles only display operations that don't require
6	//! user input.
7	//!
8	//! # Event handling
9	//!
10	//! | Event | Action |
11	//! |-------|--------|
12	//! | `StepPlanned` | Log step inclusion in plan |
13	//! | `StepFilteredOut` | Log step exclusion |
14	//! | `StepStarting` | Log step start |
15	//! | `StepCompleted` | Log step result |
16	//! | `StepSkipped` | Log skip reason |
17	//! | `WorkflowStarted` | Log workflow start |
18	//! | `WorkflowCompleted` | Log workflow summary |
19	//! | `CheckEvaluated` | Log check result |
20	
21	use crate::logging::events::{BivvyEvent, EventConsumer};
22	
23	/// Non-interactive presenter that formats events for display.
24	///
25	/// Currently used for logging/tracing. The orchestrator still handles
26	/// direct terminal output. As the architecture evolves, more display
27	/// logic will migrate from the orchestrator into this presenter.
28	pub struct EventPresenter {
29	    /// Collected messages for inspection (testing) or deferred display.
30	    messages: Vec<String>,
31	}
32	
33	impl EventPresenter {
34	    /// Create a new event presenter.
35	    pub fn new() -> Self {
36	        Self {
37	            messages: Vec::new(),
38	        }
39	    }
40	
41	    /// Get the collected messages.
42	    pub fn messages(&self) -> &[String] {
43	        &self.messages
44	    }
45	
46	    /// Drain and return all collected messages.
47	    pub fn drain_messages(&mut self) -> Vec<String> {
48	        std::mem::take(&mut self.messages)
49	    }
50	}
51	
52	impl Default for EventPresenter {
53	    fn default() -> Self {
54	        Self::new()
55	    }
56	}
57	
58	impl EventConsumer for EventPresenter {
59	    fn on_event(&mut self, event: &BivvyEvent) {
60	        match event {
