    StepDecision::Skip {
        reason: SkipReason::AutoSatisfied,
    } => {
        return self.handle_auto_satisfied(
            &eval_result,
            &step_header,
            &step_pad,
            needs_force,
            event_bus,
            step_display,
        );
    }

