    // keystrokes that arrive while in canonical (cooked) mode are lost
    // when tcsetattr switches to raw mode — the canonical buffer is not
    // drained into the non-canonical read queue. By setting raw mode
    // first, any keystroke (from user or PTY test harness) lands
    // directly in the raw input queue and is immediately available.
    //
    // Guard is dropped after the selection, restoring cooked mode for
    // normal output.
    let _raw_guard = RawModeGuard::enter(term).map_err(BivvyError::Io)?;

    // Write prompt question
    term.write_line(&prompt.question).map_err(BivvyError::Io)?;

    // Hide cursor with RAII guard — cursor is restored on drop (panic, Ctrl+C, early return).
    // Dumb terminals don't support cursor visibility, so skip the CSI sequence.
    let _cursor_guard = if dumb {
        None
    } else {
        Some(CursorGuard::new(term).map_err(BivvyError::Io)?)
    };

    // Draw initial option lines
    for (i, opt) in options.iter().enumerate() {
        let line = if i == sel {
            format!(
                "{}{} {}",
                pad,
                active_prefix.apply_to("›"),
                active_style.apply_to(&opt.label)
            )
        } else {
            format!(
                "{}{} {}",
                pad,
                inactive_prefix.apply_to("·"),
                inactive_style.apply_to(&opt.label)
            )
        };
        term.write_line(&line).map_err(BivvyError::Io)?;
    }
    term.flush().map_err(BivvyError::Io)?;

    loop {
        // Read key — terminal is already in raw mode so read_key() is a
        // no-op mode switch (raw→raw). Characters are available immediately.
        let key = term.read_key().map_err(BivvyError::Io)?;

        let chosen = match key {
            Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
            Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
            Key::Enter | Key::Char(' ') => Some(sel),
            Key::Escape => {
                // Treat Escape as "no" (matching dialoguer's abort behavior).
                // Find "no" option; fall back to default if somehow absent.
                let no_idx = options
                    .iter()
                    .position(|o| o.value == "no")
                    .unwrap_or(default_idx);
