/// RAII guard that restores the terminal cursor when dropped.
///
/// Ensures the cursor is shown even if the process panics or is
/// interrupted (Ctrl+C) while the cursor is hidden during a prompt.
struct CursorGuard<'a> {
    term: &'a Term,
}

